union all
select '2024Q4' q, ADSH, CIK, NAME, SIC, FORM, AFS, FYE, PERIOD, FILED, COUNTRYBA, STPRBA, CITYBA, ZIPBA, BAS1, BAPH, COUNTRYINC, STPRINC, EIN, FORMER, CHANGED, PREVRPT from LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_DERA_SUB_2024Q4
